
const root=document.getElementById('areiaamigos-view');
if(root){
const materials=['Areia Fina Branca','Areia Fina Amarelinha','Areia Média','Aterro','Areia'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const br=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let records=[],photo='',active='recebimento',selected=null,viewRecord=null,uncertainFields=[],reportFrom='',reportTo='';
const today=()=>new Date().toLocaleDateString('en-CA');
const upload=()=>document.getElementById('aa-file').click();
root.innerHTML='<div class="aa-head aa-head-actions"><button id="aa-new">＋ Novo recebimento</button></div><div class="aa-tabs"><button data-aa-tab="recebimento" class="active">Recebimento</button><button data-aa-tab="historico">Histórico</button><button data-aa-tab="relatorios">Relatórios</button></div><div id="aa-body"></div><input type="file" id="aa-file" accept="image/jpeg,image/png,image/webp" hidden>';
const fields=()=>['receipt','date','time','client','plate','total',...materials.map((_,i)=>'qty'+i)];
const defaults=()=>({receipt:'',date:today(),time:new Date().toTimeString().slice(0,5),client:'',plate:'',total:'',quantities:[0,0,0,0,0]});
let draft=defaults();
function setTab(tab){active=tab;root.querySelectorAll('[data-aa-tab]').forEach(b=>b.classList.toggle('active',b.dataset.aaTab===tab));draw();}
function collect(){const form=root.querySelector('#aa-form');if(!form)return;const d=new FormData(form);draft={receipt:d.get('receipt')||'',date:d.get('date')||'',time:d.get('time')||'',client:d.get('client')||'',plate:d.get('plate')||'',total:d.get('total')||'',quantities:materials.map((_,i)=>d.get('qty'+i)||'')};}
function input(name,label,type='text',value=''){const warn=uncertainFields.includes(name);return '<label class="'+(warn?'aa-uncertain':'')+'">'+label+(warn?' <span class="aa-review">⚠ Conferir</span>':'')+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(name==='receipt'||name==='date'?'required':'')+'></label>';}
function inlinePreview(r){return '<section class="aa-card aa-inline-saved"><h3>3. Pré-visualização</h3><div class="aa-preview">'+(r.image?'<img src="'+r.image+'" alt="Imagem do recibo">':'Sem imagem')+'</div><h4>Detalhes do recebimento</h4><div class="aa-details"><p>Recibo: <strong>'+esc(r.receipt)+'</strong></p><p>Data: '+esc(r.date)+' · '+esc(r.time)+'</p><p>Cliente: '+esc(r.client)+'</p><p>Placa: '+esc(r.plate)+'</p><p>Valor: R$ '+br(r.total)+'</p></div><div class="aa-share-grid"><button type="button" class="aa-share-card aa-share-wa" id="aa-share-whatsapp"><span class="aa-share-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="35" height="35" fill="currentColor"><path d="M20.5 3.5A11.6 11.6 0 0 0 12.1 0C5.5 0 .2 5.3.2 11.8c0 2.1.6 4.1 1.7 5.9L0 24l6.5-1.7a12 12 0 0 0 5.6 1.4h.1c6.5 0 11.8-5.3 11.8-11.8 0-3.2-1.2-6.1-3.5-8.4zM12.2 21.7c-1.8 0-3.6-.5-5.2-1.4l-.4-.2-3.9 1 1-3.8-.2-.4a9.7 9.7 0 0 1-1.5-5.1C2 6.4 6.5 2 12.1 2c2.6 0 5.1 1 7 2.9a9.8 9.8 0 0 1 2.9 7c0 5.4-4.4 9.8-9.8 9.8zm5.4-7.3c-.3-.1-1.8-.9-2.1-1-.3-.1-.5-.1-.7.2-.2.3-.8 1-1 1.2-.2.2-.4.2-.7.1-.3-.2-1.3-.5-2.4-1.5-.9-.8-1.5-1.8-1.7-2.1-.2-.3 0-.5.2-.7l.5-.6c.1-.2.2-.3.3-.5 0-.2 0-.4-.1-.6L9 6.8c-.2-.5-.4-.4-.7-.4h-.6c-.2 0-.6.1-.9.4-.3.3-1.1 1.1-1.1 2.6s1.1 3 1.3 3.2c.2.2 2.2 3.4 5.3 4.7.7.3 1.3.5 1.8.6.8.2 1.6.2 2.2.1.7-.1 1.8-.7 2-1.4.3-.7.3-1.3.2-1.4-.1-.2-.3-.3-.6-.4z"/></svg></span><strong>Enviar pelo<br>WhatsApp</strong><small>Compartilhar recibo com imagem e informações</small><span class="aa-share-action">➤ Compartilhar</span></button><button type="button" class="aa-share-card aa-share-mail" id="aa-share-email"><span class="aa-share-icon" aria-hidden="true">✉</span><strong>Enviar por<br>E-mail</strong><small>Enviar recibo com imagem e informações</small><span class="aa-share-action">✉ Enviar e-mail</span></button></div></section>';}

function receivable(value){const n=typeof value==='number'?value:Number(String(value||'0').replace(/\./g,'').replace(',','.'));return Math.round((Number.isFinite(n)?n:0)*5)/100;}
function receiptPanel(){const img=photo?'<img class="aa-receipt-img" src="'+photo+'" alt="Imagem do recibo anexado">':'<div class="aa-drop" id="aa-drop">☁<strong>Arraste a imagem do recibo aqui</strong><small>ou clique para selecionar JPG, PNG ou WEBP</small></div>';return '<div class="aa-columns"><section class="aa-card"><h3>1. Imagem do recibo</h3><div class="aa-image-box">'+img+'</div><div class="aa-actions"><button id="aa-upload">📎 '+(photo?'Trocar imagem':'Selecionar imagem')+'</button><button id="aa-zoom" '+(!photo?'disabled':'')+'>Ampliar</button><button id="aa-remove" '+(!photo?'disabled':'')+'>Remover</button></div></section><section class="aa-card"><h3>2. Informações extraídas da imagem</h3><div class="aa-info" id="aa-info">Anexe um recibo e use “Extrair dados”. Confira as informações antes de salvar.</div><div class="aa-actions"><button id="aa-extract" '+(!photo?'disabled':'')+'>↻ Extrair dados (OCR)</button></div><form id="aa-form"><div class="aa-fields">'+input('receipt','Nº do recibo','text',draft.receipt)+input('date','Data','date',draft.date)+input('time','Hora','time',draft.time)+'</div>'+input('client','Cliente','text',draft.client)+input('plate','Placa','text',draft.plate)+'<h4 class="aa-cargo-heading" style="background:#2a3e57;color:#f4f8ff;-webkit-text-fill-color:#f4f8ff;border:1px solid #435a77;border-radius:6px;padding:10px 12px;font-weight:700;opacity:1">Itens da carga (m³)</h4><div class="aa-items">'+materials.map((m,i)=>input('qty'+i,m,'number',draft.quantities[i])).join('')+'</div>'+input('total','Valor total (R$)','text',draft.total)+'<div class="aa-actions aa-right"><button type="button" id="aa-clear">Limpar</button><button class="aa-primary" type="submit">▣ Salvar recebimento</button></div></form></section>'+(viewRecord?inlinePreview(viewRecord):'')+'</div>';}
function savedPreview(r){
 return '<div class="aa-saved-overlay" id="aa-saved-overlay"><section class="aa-card aa-saved-modal" role="dialog" aria-modal="true" aria-label="Recibo salvo"><div class="aa-saved-header"><h3>Recibo salvo nº '+esc(r.receipt)+'</h3><button type="button" id="aa-saved-close">✕ Fechar</button></div><section class="aa-saved-content"><h3>Imagem e dados do recebimento</h3><div class="aa-preview">'+(photo?'<img src="'+photo+'" alt="Prévia do recibo">':'Nenhuma imagem anexada')+'</div><h4>Detalhes do recebimento</h4><div class="aa-details" id="aa-details"></div><div class="aa-share-grid"><button type="button" class="aa-share-card aa-share-wa" id="aa-share-whatsapp"><span class="aa-share-icon" aria-hidden="true"><img class="aa-whatsapp-logo" src="https://cdn.jsdelivr.net/npm/simple-icons@v15/icons/whatsapp.svg" alt=""></span><strong>Enviar pelo<br>WhatsApp</strong><small>Compartilhar recibo com imagem e informações</small><span class="aa-share-action">➤ Compartilhar</span></button><button type="button" class="aa-share-card aa-share-mail" id="aa-share-email"><span class="aa-share-icon" aria-hidden="true">✉</span><strong>Enviar por<br>E-mail</strong><small>Enviar recibo com imagem e informações</small><span class="aa-share-action">✉ Enviar e-mail</span></button></div></section></section></div>';
}
function openSavedReceipt(r){viewRecord=r;selected=r.id;draft={...r,total:br(r.total),quantities:[...(r.quantities||[0,0,0,0,0])]};photo=r.image||'';uncertainFields=[];setTab('recebimento');root.querySelector('.aa-inline-saved')?.scrollIntoView({behavior:'smooth',block:'nearest'});}

function history(){return '<section class="aa-card"><h3>Histórico de recebimentos</h3><div class="aa-filters"><input id="aa-search" placeholder="Buscar cliente, placa ou recibo"><select id="aa-material"><option value="">Todos os materiais</option>'+materials.map(m=>'<option>'+esc(m)+'</option>').join('')+'</select><input id="aa-from" type="date" aria-label="Data inicial"><input id="aa-to" type="date" aria-label="Data final"><button id="aa-export">Exportar CSV</button></div><div class="table-scroll"><table class="aa-table"><thead><tr><th>Data</th><th>Hora</th><th>Recibo</th><th>Cliente</th><th>Placa</th>'+materials.map(m=>'<th>'+m+'</th>').join('')+'<th>Total (R$)</th><th>A receber (5%)</th><th>Imagem</th><th>Editar</th><th>Excluir</th></tr></thead><tbody id="aa-rows"></tbody></table></div></section>';}
function draw(){const body=root.querySelector('#aa-body');body.innerHTML=(active==='recebimento'?receiptPanel():active==='historico'?history():reportPanel())+(active==='recebimento'?history():'');if(active==='recebimento'){root.querySelector('#aa-upload').onclick=upload;root.querySelector('#aa-drop')?.addEventListener('click',upload);root.querySelector('#aa-remove').onclick=()=>{photo='';uncertainFields=[];draw()};root.querySelector('#aa-zoom').onclick=()=>{const w=window.open('');if(w)w.document.write('<img src="'+photo+'" style="max-width:100%;height:auto">')};root.querySelector('#aa-clear').onclick=()=>{draft=defaults();photo='';selected=null;viewRecord=null;uncertainFields=[];draw()};root.querySelector('#aa-extract').onclick=extract;root.querySelector('#aa-form').onsubmit=save;root.querySelector('#aa-form').oninput=e=>{collect();const amountEl=root.querySelector('#aa-receivable');if(amountEl)amountEl.textContent=br(receivable(draft.total));if(e.target?.name){uncertainFields=uncertainFields.filter(x=>x!==e.target.name);const label=e.target.closest('label');label?.classList.remove('aa-uncertain');label?.querySelector('.aa-review')?.remove()}details()};details()}if(active==='recebimento'&&viewRecord){root.querySelector('#aa-share-whatsapp').onclick=()=>shareReceipt('whatsapp');root.querySelector('#aa-share-email').onclick=()=>shareReceipt('email')}if(active==='relatorios'){renderReport();root.querySelector('#aa-report-from').onchange=e=>{reportFrom=e.target.value;renderReport()};root.querySelector('#aa-report-to').onchange=e=>{reportTo=e.target.value;renderReport()};root.querySelector('#aa-report-clear').onclick=()=>{reportFrom='';reportTo='';root.querySelector('#aa-report-from').value='';root.querySelector('#aa-report-to').value='';renderReport()};root.querySelector('#aa-report-print').onclick=printReport;root.querySelector('#aa-report-pdf').onclick=downloadReportPdf;root.querySelector('#aa-report-wa').onclick=()=>shareReport('whatsapp');root.querySelector('#aa-report-mail').onclick=()=>shareReport('email')}renderRows();}

function reportPanel(){return '<svg xmlns="http://www.w3.org/2000/svg" class="aa-r-sprites" aria-hidden="true"><symbol id="aa-ri-chart" viewBox="0 0 24 24"><rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="7" width="4" height="14" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/></symbol><symbol id="aa-ri-print" viewBox="0 0 24 24"><path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a3 3 0 0 1 3-3h14a3 3 0 0 1 3 3v5a2 2 0 0 1-2 2h-2M6 14h12v7H6zM18 11h1" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></symbol><symbol id="aa-ri-download" viewBox="0 0 24 24"><path d="M12 2v13m-5-5 5 5 5-5M4 17v4h16v-4" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></symbol><symbol id="aa-ri-mail" viewBox="0 0 24 24"><rect x="2" y="5" width="20" height="14" rx="2" fill="none" stroke="currentColor" stroke-width="2"/><path d="m3 7 9 7 9-7" fill="none" stroke="currentColor" stroke-width="2"/></symbol><symbol id="aa-ri-wa" viewBox="0 0 24 24"><path fill="currentColor" d="M20.52 3.48A11.84 11.84 0 0 0 12.05 0C5.48 0 .12 5.35.12 11.93c0 2.1.55 4.15 1.6 5.96L0 24l6.28-1.65a11.9 11.9 0 0 0 5.77 1.47h.01c6.57 0 11.94-5.35 11.94-11.93 0-3.19-1.24-6.18-3.48-8.41ZM12.06 21.8c-1.78 0-3.53-.48-5.06-1.38l-.36-.21-3.72.98.99-3.62-.23-.37a9.88 9.88 0 0 1-1.52-5.27c0-5.46 4.45-9.9 9.91-9.9 2.65 0 5.13 1.03 7 2.9a9.83 9.83 0 0 1 2.89 7c0 5.45-4.45 9.88-9.9 9.88Zm5.43-7.41c-.3-.15-1.77-.87-2.05-.97-.27-.1-.47-.15-.67.15-.2.3-.77.97-.94 1.17-.17.2-.35.22-.65.07-.3-.15-1.26-.46-2.4-1.48-.89-.79-1.49-1.77-1.66-2.07-.17-.3-.02-.46.13-.61.13-.13.3-.35.45-.52.15-.18.2-.3.3-.5.1-.2.05-.37-.02-.52-.08-.15-.67-1.62-.92-2.22-.24-.58-.49-.5-.67-.5h-.57c-.2 0-.52.08-.79.37-.27.3-1.04 1.02-1.04 2.49s1.07 2.89 1.22 3.09c.15.2 2.1 3.2 5.09 4.49.71.31 1.26.5 1.69.64.71.22 1.36.19 1.87.12.57-.09 1.77-.72 2.02-1.42.25-.7.25-1.3.17-1.42-.07-.13-.27-.2-.57-.35Z"/></symbol><symbol id="aa-ri-calendar" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2" fill="none" stroke="currentColor" stroke-width="2"/><path d="M7 2v6M17 2v6M3 10h18" fill="none" stroke="currentColor" stroke-width="2"/></symbol><symbol id="aa-ri-reset" viewBox="0 0 24 24"><path d="M4 10a8 8 0 1 1 2 8M4 4v6h6" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></symbol><symbol id="aa-ri-receipt" viewBox="0 0 24 24"><rect x="5" y="2" width="14" height="20" rx="2" fill="currentColor"/><path d="M9 7h6M9 11h6M9 15h4" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/></symbol><symbol id="aa-ri-cube" viewBox="0 0 24 24"><path d="m12 1 10 5.6v10.8L12 23 2 17.4V6.6z" fill="currentColor"/><path d="m2 6.6 10 5.6 10-5.6M12 12.2V23" fill="none" stroke="#fff" stroke-width="1.7"/></symbol><symbol id="aa-ri-coins" viewBox="0 0 24 24"><ellipse cx="8" cy="6" rx="7" ry="3.5" fill="currentColor"/><path d="M1 6v9c0 5 14 5 14 0V6" fill="currentColor"/><path d="M1 10c0 5 14 5 14 0M1 14c0 5 14 5 14 0" stroke="#fff" fill="none" stroke-width="1.2"/><ellipse cx="17" cy="15" rx="6" ry="3" fill="currentColor"/><path d="M11 15v5c0 4 12 4 12 0v-5" fill="currentColor"/><path d="M11 18c0 4 12 4 12 0" stroke="#fff" fill="none" stroke-width="1.1"/></symbol></svg><section class="aa-card aa-report"><div class="aa-report-toolbar"><div><h3><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-chart"></use></svg> Relatórios de recebimento</h3><small>Resumo e distribuição por material no período selecionado</small></div><div class="aa-report-actions"><button type="button" id="aa-report-print"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-print"></use></svg> Imprimir</button><button type="button" id="aa-report-pdf"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-download"></use></svg> Baixar PDF</button><button type="button" id="aa-report-wa"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-wa"></use></svg> Enviar WhatsApp</button><button type="button" id="aa-report-mail"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-mail"></use></svg> Enviar E-mail</button></div></div><div class="aa-report-filter"><label>Data inicial <input type="date" id="aa-report-from" value="'+esc(reportFrom)+'"></label><label>Data final <input type="date" id="aa-report-to" value="'+esc(reportTo)+'"></label><button type="button" id="aa-report-clear"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-reset"></use></svg> Limpar período</button></div><div id="aa-summary"></div></section>'}
function reportData(){
 const filtered=records.filter(r=>(!reportFrom||r.date>=reportFrom)&&(!reportTo||r.date<=reportTo));
 const volumes=materials.map((_,i)=>filtered.reduce((sum,r)=>sum+(Number(r.quantities?.[i])||0),0));
 const volume=volumes.reduce((a,b)=>a+b,0);
 const total=filtered.reduce((a,r)=>a+(Number(r.total)||0),0);
 const clients=new Map();for(const r of filtered){const name=String(r.client||'Não informado').trim()||'Não informado';const key=name.toLocaleLowerCase('pt-BR');const item=clients.get(key)||{name,count:0,total:0,volume:0};item.count++;item.total+=Number(r.total)||0;item.volume+=(r.quantities||[]).reduce((s,q)=>s+(Number(q)||0),0);clients.set(key,item)}const byClient=[...clients.values()].sort((a,b)=>b.total-a.total);return {filtered,volumes,volume,total,byClient};
}
function renderReport(){
 const {filtered,volumes,volume,total,byClient}=reportData();
 const materialColors=[['#e9dfd1','#cdbda8'],['#ffd344','#e8a900'],['#9ca7b8','#6e7c92'],['#d79a5c','#a76836'],['#ead4b1','#cbb18b']];
 const piles=materials.map((m,i)=>{const [light,dark]=materialColors[i];return '<svg class="aa-sand-art" viewBox="0 0 64 48" aria-hidden="true"><ellipse cx="32" cy="42" rx="29" ry="5" fill="#34445a" opacity=".12"/><path d="M5 37Q10 33 17 24L26 10Q30 5 35 10L47 26Q53 32 59 37Q61 43 50 44H14Q3 43 5 37Z" fill="'+dark+'"/><path d="M6 37Q14 30 26 10Q29 6 33 9Q29 18 25 27Q22 35 15 43H13Q3 42 6 37Z" fill="'+light+'"/><path d="M34 12 44 28 54 37Q50 42 39 42Q44 33 34 12Z" fill="'+dark+'" opacity=".45"/><path d="M13 38q7-4 13-2M35 39q6-2 12 0" fill="none" stroke="'+light+'" stroke-width="2" opacity=".7"/></svg>'});
 root.querySelector('#aa-summary').innerHTML='<div class="aa-report-layout"><div class="aa-report-kpis"><div class="aa-report-kpi aa-kpi-blue"><span class="aa-kpi-icon"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-receipt"></use></svg></span><div>Total de recebimentos<strong>'+filtered.length+'</strong></div></div><div class="aa-report-kpi aa-kpi-green"><span class="aa-kpi-icon"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-cube"></use></svg></span><div>Volume recebido<strong>'+br(volume)+' m³</strong></div></div><div class="aa-report-kpi aa-kpi-purple"><span class="aa-kpi-icon"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-coins"></use></svg></span><div>Valor total<strong>R$ '+br(total)+'</strong></div></div><div class="aa-report-kpi aa-kpi-receivable" style="background:#fff2d9"><span class="aa-kpi-icon" style="color:#c27b00"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-coins"></use></svg></span><div>Total a receber (5%)<strong>R$ '+br(receivable(total))+'</strong></div></div></div><div class="aa-report-materials"><h4><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-chart"></use></svg> Volume por tipo de material</h4><div class="table-scroll"><table><thead><tr><th>Material</th><th>Volume (m³)</th><th>% do total</th><th>Distribuição</th></tr></thead><tbody>'+materials.map((m,i)=>{const percent=volume?volumes[i]/volume*100:0;return '<tr><td>'+piles[i]+' <span>'+esc(m)+'</span></td><td>'+br(volumes[i])+'</td><td>'+percent.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%</td><td><div class="aa-report-track"><span style="width:'+Math.max(0,Math.min(100,percent))+'%"></span></div></td></tr>'}).join('')+'</tbody></table></div></div></div><section class="aa-report-clients" style="margin-top:20px;padding:20px;border:1px solid #d5e4f5;border-radius:18px;background:white"><h4 style="font-size:19px;color:#082e64;margin:0 0 16px"><svg class="aa-r-icon" aria-hidden="true"><use href="#aa-ri-coins"></use></svg> Valores a receber por cliente</h4><div class="table-scroll"><table style="width:100%;border-collapse:collapse"><thead><tr><th>Cliente</th><th>Recebimentos</th><th>Volume (m³)</th><th>Valor vendido</th><th>A receber (5%)</th><th>Distribuição</th></tr></thead><tbody>'+(byClient.length?byClient.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+x.count+'</td><td>'+br(x.volume)+'</td><td>R$ '+br(x.total)+'</td><td><strong>R$ '+br(receivable(x.total))+'</strong></td><td><div class="aa-report-track"><span style="width:'+(total?Math.min(100,x.total/total*100):0)+'%"></span></div></td></tr>').join(''):'<tr><td colspan="6">Nenhum recebimento no período.</td></tr>')+'</tbody></table></div></section>';
}
function reportMessage(){
 const {filtered,volumes,volume,total}=reportData();
 const range=(reportFrom?reportFrom.split('-').reverse().join('/'):'Início')+' a '+(reportTo?reportTo.split('-').reverse().join('/'):'Hoje / todos');
 return 'COLAFIX — RELATÓRIO AREIA AMIGOS\nPeríodo: '+range+'\nRecebimentos: '+filtered.length+'\nVolume total: '+br(volume)+' m³\nValor total: R$ '+br(total)+'\nTotal a receber (5%): R$ '+br(receivable(total))+'\n\nClientes:\n'+reportData().byClient.map(x=>x.name+': R$ '+br(receivable(x.total))).join('\n')+'\n\n'+materials.map((m,i)=>m+': '+br(volumes[i])+' m³ ('+(volume?(volumes[i]/volume*100).toFixed(1).replace('.',','):'0')+'%)').join('\n');
}
function reportHtml(){
 const {filtered,volumes,volume,total,byClient}=reportData();
 const rows=materials.map((m,i)=>'<tr><td>'+esc(m)+'</td><td>'+br(volumes[i])+' m³</td><td>'+(volume?(volumes[i]/volume*100).toFixed(1).replace('.',','):'0')+'%</td></tr>').join('');
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório Areia Amigos</title><style>body{font:14px Arial,sans-serif;margin:32px;color:#17304d}h1{font-size:22px}p{line-height:1.8}table{border-collapse:collapse;width:100%;margin-top:18px}th,td{padding:11px;text-align:left;border:1px solid #ccd7e4}th{background:#eaf2fc}@page{size:A4;margin:18mm}</style></head><body><h1>COLAFIX — Relatórios de recebimento</h1><p>Período: '+esc(reportFrom||'Todos')+' a '+esc(reportTo||'Todos')+'<br>Total de recebimentos: <b>'+filtered.length+'</b><br>Volume recebido: <b>'+br(volume)+' m³</b><br>Valor total: <b>R$ '+br(total)+'</b><br>Total a receber (5%): <b>R$ '+br(receivable(total))+'</b></p><h2>Volume por material</h2><table><thead><tr><th>Material</th><th>Volume</th><th>% do total</th></tr></thead><tbody>'+rows+'</tbody></table><h2>Valores a receber por cliente</h2><table><thead><tr><th>Cliente</th><th>Recebimentos</th><th>Valor vendido</th><th>A receber (5%)</th></tr></thead><tbody>'+byClient.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.count+'</td><td>R$ '+br(x.total)+'</td><td>R$ '+br(receivable(x.total))+'</td></tr>').join('')+'</tbody></table></body></html>';
}
function printReport(){const w=window.open('','_blank');if(!w)return alert('Permita janelas pop-up para imprimir.');w.document.open();w.document.write(reportHtml());w.document.close();w.focus();w.print()}
function reportPdfName(){return 'colafix-areia-amigos-'+(reportFrom||'inicio')+'-'+(reportTo||'todos')+'.pdf'}
async function buildReportPdf(){
 if(!window.jspdf){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Não foi possível carregar o gerador de PDF.'));document.head.appendChild(s)})}
 const {jsPDF}=window.jspdf;const pdf=new jsPDF();const {filtered,volumes,volume,total,byClient}=reportData();let y=20;
 pdf.setFont('helvetica','bold');pdf.setFontSize(17);pdf.text('COLAFIX - RELATORIO AREIA AMIGOS',14,y);y+=12;
 pdf.setFontSize(11);pdf.setFont('helvetica','normal');
 const lines=['Periodo: '+(reportFrom||'Todos')+' a '+(reportTo||'Todos'),'Total de recebimentos: '+filtered.length,'Volume recebido: '+br(volume)+' m3','Valor total: R$ '+br(total),'Total a receber (5%): R$ '+br(receivable(total)),'','VOLUME POR TIPO DE MATERIAL'];
 for(const line of lines){pdf.text(line,14,y);y+=9}
 materials.forEach((m,i)=>{pdf.text(m+': '+br(volumes[i])+' m3 - '+(volume?(volumes[i]/volume*100).toFixed(1):'0')+'%',14,y);y+=9});
 y+=7;pdf.setFont('helvetica','bold');pdf.text('VALORES A RECEBER POR CLIENTE',14,y);y+=9;pdf.setFont('helvetica','normal');for(const x of byClient){if(y>275){pdf.addPage();y=20}const line=x.name+' | '+x.count+' recibos | Venda R$ '+br(x.total)+' | 5% R$ '+br(receivable(x.total));pdf.splitTextToSize(line,180).forEach(t=>{pdf.text(t,14,y);y+=7})}return pdf;
}
async function downloadReportPdf(){try{const pdf=await buildReportPdf();pdf.save(reportPdfName())}catch(e){alert('Erro ao gerar PDF: '+e.message)}}
async function shareReport(channel){
 const message=reportMessage(),url=channel==='whatsapp'?'https://wa.me/?text='+encodeURIComponent(message):'mailto:?subject='+encodeURIComponent('Relatório Areia Amigos - Colafix')+'&body='+encodeURIComponent(message+'\n\nAnexe o PDF do relatório.');
 // O link WhatsApp e mailto não permitem anexar PDF automaticamente no desktop.
 try{
  const pdf=await buildReportPdf();const blob=pdf.output('blob');const file=new File([blob],reportPdfName(),{type:'application/pdf'});
  if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({title:'Relatório Areia Amigos',text:message,files:[file]});return}
  pdf.save(reportPdfName());
 }catch(e){if(e.name==='AbortError')return;alert('Não foi possível preparar o PDF: '+e.message);return}
 if(channel==='whatsapp')window.open(url,'_blank','noopener');else window.location.href=url;
 alert('O PDF foi baixado. Anexe o arquivo à mensagem antes de enviar.');
}

function shareText(){
 const date=draft.date?draft.date.split('-').reverse().join('/'):'—';
 const qty=materials.map((m,i)=>({name:m,value:Number(draft.quantities?.[i]||0)})).filter(x=>x.value>0).map(x=>x.name+': '+x.value+' m³').join('\n')||'Não informado';
 return 'RECEBIMENTO DE AREIA — COLAFIX\nRecibo: '+(draft.receipt||'—')+'\nData: '+date+'\nHora: '+(draft.time||'—')+'\nCliente: '+(draft.client||'—')+'\nPlaca: '+(draft.plate||'—')+'\nMateriais:\n'+qty+'\nValor total: R$ '+(draft.total||'0,00');
}
function downloadReceiptImage(){
 if(!photo)return;
 const link=document.createElement('a');link.href=photo;link.download='recibo-'+(draft.receipt||'areia-amigos')+'.'+(photo.startsWith('data:image/png')?'png':photo.startsWith('data:image/webp')?'webp':'jpg');document.body.appendChild(link);link.click();link.remove();
}
async function shareReceipt(channel){
 collect();if(!photo)return alert('Anexe a imagem do recibo primeiro.');
 const message=shareText();
 if(navigator.share&&navigator.canShare){
  try{
   const response=await fetch(photo),blob=await response.blob();
   const extension=blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg';
   const file=new File([blob],'recibo-'+(draft.receipt||'areia-amigos')+'.'+extension,{type:blob.type||'image/jpeg'});
   if(navigator.canShare({files:[file]})){
    await navigator.share({title:'Recibo '+(draft.receipt||''),text:message,files:[file]});
    return;
   }
  }catch(err){if(err.name==='AbortError')return}
 }
 downloadReceiptImage();
 if(channel==='whatsapp')window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener');
 else window.location.href='mailto:?subject='+encodeURIComponent('Recibo Areia Amigos nº '+(draft.receipt||''))+'&body='+encodeURIComponent(message+'\n\nAnexe a imagem do recibo baixada pelo navegador.');
 alert('A foto foi baixada. Anexe o arquivo do recibo na conversa ou no e-mail antes de enviar.');
}
function details(){const el=root.querySelector('#aa-details');if(el)el.innerHTML='<p>Recibo: <strong>'+esc(draft.receipt||'—')+'</strong></p><p>Data: '+esc(draft.date||'—')+' · '+esc(draft.time||'—')+'</p><p>Cliente: '+esc(draft.client||'—')+'</p><p>Placa: '+esc(draft.plate||'—')+'</p><p>Valor: R$ '+esc(draft.total||'0,00')+'</p><p><strong>Valor a receber (5%): R$ '+br(receivable(draft.total))+'</strong></p>';}
function renderRows(){const tbody=root.querySelector('#aa-rows');if(!tbody)return;const q=(root.querySelector('#aa-search')?.value||'').toLowerCase(),mat=root.querySelector('#aa-material')?.value||'',from=root.querySelector('#aa-from')?.value||'',to=root.querySelector('#aa-to')?.value||'';const list=records.filter(r=>(!q||[r.receipt,r.client,r.plate].some(v=>String(v||'').toLowerCase().includes(q)))&&(!mat||Number(r.quantities?.[materials.indexOf(mat)]||0)>0)&&(!from||r.date>=from)&&(!to||r.date<=to)).sort((a,b)=>{const na=Number(String(a.receipt||'').replace(/\D/g,'')),nb=Number(String(b.receipt||'').replace(/\D/g,''));return nb-na||String(b.receipt||'').localeCompare(String(a.receipt||''),'pt-BR',{numeric:true})});tbody.innerHTML=list.map(r=>'<tr><td>'+esc(r.date?.split('-').reverse().join('/'))+'</td><td>'+esc(r.time)+'</td><td>'+esc(r.receipt)+'</td><td>'+esc(r.client)+'</td><td>'+esc(r.plate)+'</td>'+(r.quantities||[]).map(n=>'<td>'+(Number(n)?esc(n):'—')+'</td>').join('')+'<td>'+br(r.total)+'</td><td><strong>'+br(receivable(r.total))+'</strong></td><td><button data-aa-open="'+esc(r.id)+'">🖼️ Ver</button></td><td><button type="button" data-aa-edit="'+esc(r.id)+'" title="Editar recibo" aria-label="Editar recibo '+esc(r.receipt)+'">✏️ Editar</button></td><td><button type="button" data-aa-delete="'+esc(r.id)+'" title="Excluir recibo" aria-label="Excluir recibo '+esc(r.receipt)+'">🗑️</button></td></tr>').join('')||'<tr><td colspan="14">Nenhum recebimento encontrado.</td></tr>';tbody.querySelectorAll('[data-aa-open]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.aaOpen);if(!r)return;openSavedReceipt(r)});tbody.querySelectorAll('[data-aa-edit]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.aaEdit);if(!r)return;selected=r.id;draft={...r,total:br(r.total),quantities:[...(r.quantities||[0,0,0,0,0])]};photo=r.image||'';uncertainFields=[];root.querySelector('#aa-saved-overlay')?.remove();if(document.querySelector('#dashboard-view')){if(location.hash!=='#areiaamigos')location.hash='areiaamigos';document.querySelectorAll('.page-view').forEach(view=>{view.hidden=view.id!=='areiaamigos-view'})}setTab('recebimento');root.querySelector('#aa-info').textContent='✏️ Editando recibo nº '+r.receipt+'. Confira os dados e clique em Salvar recebimento para atualizar o registro existente.';root.querySelector('#aa-form')?.scrollIntoView({behavior:'smooth',block:'start'})});tbody.querySelectorAll('[data-aa-delete]').forEach(b=>b.onclick=async()=>{const r=records.find(x=>x.id===b.dataset.aaDelete);if(!r)return;if(!confirm('Excluir definitivamente o recibo nº '+r.receipt+'? A imagem e os dados deste registro também serão excluídos.'))return;b.disabled=true;try{const response=await fetch('/api/areia-amigos/'+encodeURIComponent(r.id),{method:'DELETE'});const j=await response.json();if(!response.ok)throw Error(j.error||'Falha ao excluir');records=j.records;if(selected===r.id){selected=null;draft=defaults();photo='';uncertainFields=[]}renderRows();alert('Recibo nº '+r.receipt+' excluído.')}catch(e){b.disabled=false;alert(e.message)}});}
async function load(){try{const r=await fetch('/api/areia-amigos');if(!r.ok)throw Error('Falha ao carregar');records=(await r.json()).records||[];draw()}catch(e){root.querySelector('#aa-body').innerHTML='<p>Erro ao carregar recebimentos: '+esc(e.message)+'</p>'}}
async function save(e){e.preventDefault();collect();const duplicate=records.find(r=>String(r.receipt||'').trim()===String(draft.receipt||'').trim()&&String(r.id)!==String(selected||''));if(duplicate)return alert('⚠ Recibo nº '+draft.receipt+' já está cadastrado no histórico. Não é permitido cadastrar novamente.');if(!photo)return alert('Anexe a imagem do recibo antes de salvar.');const amount=String(draft.total).replace(/\./g,'').replace(',','.');const entry={...draft,id:selected||crypto.randomUUID(),total:Number(amount)||0,quantities:draft.quantities.map(x=>Number(x)||0),image:photo};try{const r=await fetch('/api/areia-amigos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)});const j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível salvar');records=j.records;draft=defaults();photo='';selected=null;setTab('historico');alert('Recebimento salvo com imagem!')}catch(err){alert(err.message)}}
function fileToData(file){return new Promise((resolve,reject)=>{if(file.size>5*1024*1024)return reject(Error('Imagem acima de 5 MB. Reduza a foto.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
root.querySelector('#aa-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{collect();photo=await fileToData(file);draw()}catch(err){alert(err.message)}e.target.value=''};
root.querySelectorAll('[data-aa-tab]').forEach(b=>b.onclick=()=>{collect();setTab(b.dataset.aaTab)});root.querySelector('#aa-new').onclick=()=>{draft=defaults();photo='';selected=null;setTab('recebimento')};
root.addEventListener('input',e=>{if(['aa-search','aa-material','aa-from','aa-to'].includes(e.target.id))renderRows()});
root.addEventListener('click',e=>{if(e.target.id!=='aa-export')return;const head=['Data','Hora','Recibo','Cliente','Placa',...materials,'Total','A receber (5%)'];const lines=records.map(r=>[r.date,r.time,r.receipt,r.client,r.plate,...r.quantities,r.total,receivable(r.total)]);const csv=[head,...lines].map(a=>a.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='areia-amigos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
async function extract(){
 collect();const info=root.querySelector('#aa-info');info.textContent='IA analisando a escrita do recibo...';
 try{
  const response=await fetch('/api/areia-amigos/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:photo})});
  const result=await response.json();if(!response.ok)throw Error(result.error||'Falha na leitura');
  const d=result.data||{};if(d.receipt)draft.receipt=d.receipt;if(d.date)draft.date=d.date;if(d.time)draft.time=d.time;if(d.client)draft.client=d.client;if(d.plate)draft.plate=d.plate;
  if(d.total!=null&&Number.isFinite(d.total))draft.total=d.total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(Array.isArray(d.quantities))d.quantities.forEach((v,i)=>{if(v!=null&&Number.isFinite(v)&&v>=0)draft.quantities[i]=v});
  uncertainFields=[...new Set([...(d.uncertain_fields||[]),...(['receipt','date','time','client','plate','total'].filter(k=>d[k]==null)),...(Array.isArray(d.quantities)?d.quantities.map((v,i)=>v==null?'qty'+i:null).filter(Boolean):[])])];
  draw();root.querySelector('#aa-info').textContent='Leitura por IA concluída. Confira os dados manuscritos antes de salvar.'+(uncertainFields.length?' Campos em amarelo precisam de conferência.':'')+(d.warnings?.length?' Observações: '+d.warnings.join('; '):'');
 }catch(e){info.textContent='Não foi possível ler com IA: '+e.message+'. Confira a configuração e preencha manualmente.'}
}
load();
}
